class Commands:
    """``sbx.commands``: run, stream and cancel commands."""

    def __init__(self, sandbox: Sandbox) -> None:
        self._sandbox = sandbox

    def stream(
        self,
        command: str,
        *,
        cwd: Optional[str] = None,
        env: Optional[Mapping[str, str]] = None,
        timeout_seconds: Optional[int] = None,
    ) -> CommandStream:
        """Typed frames (``started``, ``stdout``, ``stderr``, ``exit``, ``error``) as they
        arrive. Use ``with``: closing the stream cancels the command. ``env`` is for
        plain, non-secret variables only."""
        body = present(
            command=command,
            cwd=cwd,
            env=dict(env) if env is not None else None,
            timeoutSeconds=timeout_seconds,
        )
        return self._sandbox._sandboxes.commands.run(self._sandbox.id, body=body)

    def run(
        self,
        command: str,
        *,
        cwd: Optional[str] = None,
        env: Optional[Mapping[str, str]] = None,
        timeout_seconds: Optional[int] = None,
        on_stdout: Optional[OutputCallback] = None,
        on_stderr: Optional[OutputCallback] = None,
    ) -> CommandResult:
        """Run a command to its end and return the whole exit record.

        A non-zero exit code, a timeout (``timed_out``), a signal (``signal``, with
        ``exit_code`` None), a cancel (``cancelled``) and a command that never started
        (``error``, with ``exit_code`` None) are all returned, not raised. Raises only
        ``CommandFailedError`` on an ``error`` frame and ``CommandIncompleteError`` when the
        stream ends (or the connection drops) without an ``exit`` frame. Never retried:
        whether an incomplete command ran is unknown, so it is not sent again."""
        out: List[str] = []
        err: List[str] = []
        stream = self.stream(command, cwd=cwd, env=env, timeout_seconds=timeout_seconds)
        last: Optional[ExitFrame] = None
        failure: Optional[BaseException] = None
        with stream:
            try:
                for frame in stream:
                    if isinstance(frame, StdoutFrame):
                        out.append(frame.data)
                        if on_stdout is not None:
                            on_stdout(frame.data)
                    elif isinstance(frame, StderrFrame):
                        err.append(frame.data)
                        if on_stderr is not None:
                            on_stderr(frame.data)
                    elif isinstance(frame, ExitFrame):
                        last = frame
                        break
                    elif isinstance(frame, ErrorFrame):
                        failure = CommandFailedError(
                            f"sandboxes.commands.run: {frame.message}",
                            exec_id=stream.exec_id,
                            stdout="".join(out),
                            stderr="".join(err),
                        )
                        break
            except ConnectionError as error:
                if not stream.opened:
                    raise
                raise CommandIncompleteError(
                    "sandboxes.commands.run: the stream broke before the exit frame; "
                    f"whether the command finished is unknown ({error})",
                    exec_id=stream.exec_id,
                    stdout="".join(out),
                    stderr="".join(err),
                ) from error
        if failure is not None:
            raise failure
        if last is None:
            raise CommandIncompleteError(
                "sandboxes.commands.run: the stream ended without an exit frame; "
                "whether the command finished is unknown",
                exec_id=stream.exec_id,
                stdout="".join(out),
                stderr="".join(err),
            )
        return CommandResult.from_exit(last, "".join(out), "".join(err), stream.exec_id)

    def cancel(self, exec_id: str) -> Dict[str, Any]:
        """Cancel a running command by the ``exec_id`` of its ``started`` frame."""
        api = self._sandbox._sandboxes.commands
        return api.cancel(self._sandbox.id, exec_id)


class Files:
    """``sbx.files``: list, read, write, upload and download files inside the sandbox.

    Every path is relative to /workspace (``src/app.py``); an absolute path under it is sent
    in that form (/workspace/src/app.py as ``src/app.py``). A path outside /workspace, or
    with a ``.`` or ``..`` segment, a backslash or a control character, raises
    ``ConfigurationError`` (``invalid_path``) before any request."""

    def __init__(self, sandbox: Sandbox) -> None:
        self._sandbox = sandbox

    @property
    def _api(self) -> Any:
        return self._sandbox._sandboxes.files

    def list(self, path: str = ".") -> List[Dict[str, Any]]:
        """The entries (``name``, ``size``, ``mode``, ``directory``) of one folder; ``"."`` (the
        default) or /workspace is the root."""
        folder = files_path(path, "sandboxes.files.list", root=True)
        raw = self._api.list(self._sandbox.id, path=folder)
        return list(raw.get("entries", []))

    def read(
        self,
        path: str,
        max_bytes: Optional[int] = None,
    ) -> Union[str, bytes]:
        """A bounded read: ``str`` for a UTF-8 file, ``bytes`` for anything else."""
        where = files_path(path, "sandboxes.files.read")
        raw = self._api.read(self._sandbox.id, where, max_bytes=max_bytes)
        file = raw.get("file", {})
        content = file.get("content", "")
        if file.get("encoding") == "base64":
            return base64.b64decode(content)
        return content

    def write(self, path: str, data: Union[str, bytes]) -> Dict[str, Any]:
        """Write a small text (``str``) or binary (``bytes``) file, audited."""
        where = files_path(path, "sandboxes.files.write")
        if isinstance(data, str):
            body = {"content": data, "encoding": "utf8"}
        else:
            encoded = base64.b64encode(bytes(data)).decode("ascii")
            body = {"content": encoded, "encoding": "base64"}
        return self._api.write(self._sandbox.id, where, body=body)

    def upload(self, path: str, data_or_file: UploadBody) -> Dict[str, Any]:
        """Upload raw bytes, a path or a binary file (at most 64 MiB). The folder must exist."""
        where = files_path(path, "sandboxes.files.upload")
        return self._api.upload(self._sandbox.id, where, body=data_or_file)

    def download(self, path: str, *, max_bytes: int = DOWNLOAD_LIMIT) -> bytes:
        """A file's raw bytes, at most ``max_bytes`` (64 MiB unless raised or lowered): a larger
        file raises ``PayloadTooLargeError`` and nothing past the limit is kept."""
        where = files_path(path, DOWNLOAD)
        stream = self._api._stream(self._sandbox.id, where, max_bytes)
        return b"".join([chunk for chunk in stream])

    def download_to(
        self,
        path: str,
        local_path: Union[str, "os.PathLike[str]"],
        *,
        max_bytes: int = DOWNLOAD_LIMIT,
    ) -> str:
        """Stream a file to ``local_path``: written to a temporary file beside it and renamed
        only once every byte arrived, so a failure never leaves a partial file there. At most
        ``max_bytes`` (64 MiB unless raised or lowered): a larger file raises
        ``PayloadTooLargeError`` and its partial file is removed."""
        where = files_path(path, DOWNLOAD)
        target = os.fspath(local_path)
        folder = os.path.dirname(os.path.abspath(target))
        handle = tempfile.NamedTemporaryFile(
            dir=folder, prefix=".sandbox-download-", delete=False
        )
        try:
            with handle:
                stream = self._api._stream(self._sandbox.id, where, max_bytes)
                for chunk in stream:
                    handle.write(chunk)
            os.replace(handle.name, target)
        except BaseException:
            try:
                os.unlink(handle.name)
            except OSError:
                pass
            raise
        return target

    def remove(self, path: str, *, recursive: bool = False) -> Dict[str, Any]:
        """Delete a file, or a folder and its contents with ``recursive=True``."""
        where = files_path(path, "sandboxes.files.remove")
        flag = True if recursive else None
        return self._api.remove(self._sandbox.id, where, recursive=flag)

    def move(self, src: str, dst: str) -> Dict[str, Any]:
        """Move or rename a file or folder."""
        move = "sandboxes.files.rename"
        source = files_path(src, move, name="src")
        target = files_path(dst, move, name="dst")
        body = {"from": source, "to": target}
        return self._api.rename(self._sandbox.id, body=body)

    def make_dir(self, path: str) -> Dict[str, Any]:
        """Create a folder (and its parents)."""
        where = files_path(path, "sandboxes.files.makeDir")
        return self._api.make_dir(self._sandbox.id, where)


class Snapshots:
    """``sbx.snapshots``: file snapshots; ``restore`` makes a new sandbox."""

    def __init__(self, sandbox: Sandbox) -> None:
        self._sandbox = sandbox

    def create(self) -> Dict[str, Any]:
        """Snapshot the files; returns the snapshot record."""
        raw = self._sandbox._sandboxes.snapshots.create(self._sandbox.id)
        return dict(raw.get("snapshot", {}))

    def list(self) -> List[Dict[str, Any]]:
        """The sandbox's snapshot records."""
        raw = self._sandbox._sandboxes.snapshots.list(self._sandbox.id)
        return list(raw.get("snapshots", []))

    def restore(
        self,
        snapshot_id: str,
        *,
        name: Optional[str] = None,
        size: Optional[str] = None,
        limits: Optional[Mapping[str, Any]] = None,
        network: Optional[str] = None,
        network_policy: Optional[Mapping[str, Any]] = None,
        idle_ttl_seconds: Optional[int] = None,
    ) -> Sandbox:
        """A NEW sandbox from the snapshot; this one is unchanged. Never retried. The new handle
        shares this one's connection (and closes it on exit if this one would)."""
        body = present(
            name=name,
            size=size,
            limits=dict(limits) if limits is not None else None,
            network=network,
            networkPolicy=dict(network_policy) if network_policy is not None else None,
            idleTtlSeconds=idle_ttl_seconds,
        )
        api = self._sandbox._sandboxes.snapshots
        restored = api.restore(self._sandbox.id, snapshot_id, body=body)
        restored._owns_pool = self._sandbox._owns_pool
        return restored


